export function slugify(s: string): string {
  return s.normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase();
}

// Sirf tab jab taluka apne AC ke jile se alag jile me ho (Wada -> Palghar)
export const talukaHomeOverride: Record<string, string> = {"Wada": "Palghar"};

export const districtSlug = (d: string) => slugify(d);
export const talukaPath = (district: string, taluka: string) =>
  `/taluka/${slugify(district)}/${slugify(taluka)}`;
// AC page se link: taluka apne home jile ke path par hota hai
export const talukaLink = (district: string, taluka: string) =>
  talukaPath(talukaHomeOverride[taluka] ?? district, taluka);
export const districtPath = (district: string) => `/jila/${slugify(district)}`;
